select
		  b.idPagoComplementoFolioFactura
		, c.rfc
		, c.email
		, c.fechatimbrado
		, c.uuid
		, c.xml
		, c.serie
		, c.folio
		, c.subtotal
		, c.total
		, d.*
		, d.montoFactura
		, b.montoPago pagoComplemento
		, d.monedaPago
		, d.equivalencia
		, d.parcialidad
		, d.importeSaldoAnterior
		, d.importePagado
		, d.importePosterior
		, 0 saldoControl
		, a.*
		-- select *
		from pagocomplemento a 
		join pagocomplementofoliofactura b on a.id = b.idpagocomplemento
--		join pagocomplementofoliofacturadet d on d.idPagoComplementoFolioFactura = b.idPagoComplementoFolioFactura
--		join facturas c on c.idfactura = d.idfactura
		where 1=1 
--		and a.id = 5524
		and a.uuid = 'ac65232c-7b00-42b5-a0d7-856a5d44b8d4'
		and b.estatus = 1
		order by c.fechatimbrado desc;
		
		select *
		from pagocomplementofoliofacturadet
		where idPagoComplementoFolioFacturaDet = 12117;
		
		
		--- folios
SELECT c.idFolioFactura
                     , a.idFactura
                     , c.razonSocial
                     , a.uuid             
                     , a.serie
                     , a.folio
                     , a.total
                     , a.subtotal
                     , a.fechaTimbrado
                     , 1 pagoRelacionado
                     , a.rfc
                     , a.ticket
                     , a.estatusPago
                     , c.folioFactura
                     , (select count(1)
                       from pagocomplementofoliofactura pc
                          , pagocomplementofoliofacturadet pcd
                       where pc.idPagoComplementoFolioFactura = pcd.idPagoComplementoFolioFactura
                       and   pcd.idFactura = a.idFactura
                       and   pc.estatus = 1) facturaAsignada
                     , c.orden
                from facturas a 
                join clientes b on (a.idCliente = b.idCliente)
                left join vw_foliofacturadet c on (a.idFactura = c.idFactura)
                where a.metodoPago = 'PPD'
                AND   a.idComprobante = 'I'
                and   a.versionFacturacionSat = '4.0'
--                and  date_format(a.fechaTimbrado,'%Y-%m-%d') >= '2026-02-20'
	--		    and  date_format(a.fechaTimbrado,'%Y-%m-%d') <= '2026-02-20'
			    and  a.idFactura in (22282894,22282964,22282967)
				order by a.idFactura;
        
        -- if (pFolio > 0) then
        --        SET @Condition = CONCAT(@Condition,' and  c.folioFactura = ',pFolio);
        -- end if;
		
		-- Pagos
    SELECT p.idPago
    , p.numeroCuenta
    , p.fechaHoraMovimiento
    , p.concepto
    , p.importe
    , p.folioBanco
    , p.refInterbancaria
    , p.folioCliente
    , p.tipoDivisa
    , p.folioOperacion
    , p.formaPago
    , e.idEstatusPago
    , e.descripcion
    , e.idEstatusPago
    FROM pagos p 
    inner join catestatuspago e on p.estatus = e.idEstatusPago
    where '2026-02-20' <= p.fechaHoraMovimiento and p.fechaHoraMovimiento <= DATE_ADD('2026-02-20', INTERVAL 1 DAY)
    -- and pidStatusPago = e.idEstatusPago
    and  32597.16 = p.importe
    order by p.fechaHoraMovimiento desc;

		
