        select
		  b.idPagoComplementoFolioFactura
		, c.rfc
		, c.email
		, c.fechatimbrado
		, c.uuid
		, c.xml
		, c.serie
		, c.folio
		, c.subtotal
		, c.total
		, d.montoFactura
		, b.montoPago pagoComplemento
		, d.monedaPago
		, d.equivalencia
		, d.parcialidad
		, d.importeSaldoAnterior
		, d.importePagado
		, d.importePosterior
		, 0 saldoControl
		, c.idfactura
		from pagocomplemento a 

		join pagocomplementofoliofactura b on a.id = b.idpagocomplemento

		join pagocomplementofoliofacturadet d on d.idPagoComplementoFolioFactura = b.idPagoComplementoFolioFactura
		join facturas c on c.idfactura = d.idfactura
		where a.id in (8595,8601) 
		and b.estatus = 1
		order by c.fechatimbrado desc;

		
